{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "pk/_schema/architecture-entry.schema.json",
  "title": "Architecture Knowledge Entry",
  "description": "pk/architecture/ 條目 schema：C4-compatible 架構模型（System / Container / Component / Responsibility / Relationship / Interface / Constraint / Decision）。YAML 或 JSON。",
  "type": "object",
  "allOf": [{"$ref": "common.schema.json#/$defs/governanceFields"}],
  "required": ["id", "pkClass", "validationState", "confidence", "evidence", "governanceIssueRef", "c4Level", "name", "responsibility"],
  "properties": {
    "id": {"type": "string", "pattern": "^arch:"},
    "pkClass": {"const": "pk-architecture"},
    "c4Level": {
      "type": "string",
      "enum": ["system-context", "container", "component"],
      "description": "C4 層級"
    },
    "name": {"type": "string"},
    "parent": {"type": ["string", "null"], "description": "上層 arch: 條目 id（System 層為 null）"},
    "children": {"type": "array", "items": {"type": "string"}, "description": "下層 arch: 條目 id"},
    "responsibility": {
      "type": "object",
      "required": ["owns"],
      "properties": {
        "owns": {"type": "array", "items": {"type": "string"}, "description": "負責什麼"},
        "excludes": {"type": "array", "items": {"type": "string"}, "description": "不負責什麼"}
      }
    },
    "relationships": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["direction", "target", "description"],
        "properties": {
          "direction": {"type": "string", "enum": ["outgoing", "incoming"]},
          "target": {"type": "string", "description": "對方 arch: 條目 id 或外部系統名"},
          "description": {"type": "string"}
        }
      }
    },
    "interfaces": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "name", "kind"],
        "properties": {
          "id": {"type": "string", "description": "如 if:chart-management-api/charts-rest"},
          "name": {"type": "string"},
          "kind": {"type": "string", "enum": ["api", "event", "data-contract"]},
          "specRef": {"type": ["string", "null"], "description": "OpenAPI／schema 檔的可回溯位址（repo 路徑或 URI）"}
        }
      }
    },
    "constraints": {"type": "array", "items": {"type": "string"}},
    "decisions": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["decision", "rationale"],
        "properties": {
          "decision": {"type": "string"},
          "rationale": {"type": "string"},
          "alternativesRejected": {"type": "array", "items": {"type": "string"}}
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "pk/_schema/code-graph.schema.json",
  "title": "Code Graph Node / Edge",
  "description": "pk/code-graph/nodes.jsonl 與 edges.jsonl 的逐行 schema。Node 7 種、Relation 9 種（pk-conceptual-model.md 第 3.2 節）。每行一個 JSON object。",
  "$defs": {
    "node": {
      "type": "object",
      "required": ["id", "nodeType", "name", "validationState"],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^(Product|Capability|Component|Interface|Repository|Module|CodeEntity):.+",
          "description": "格式 <NodeType>:<name>，如 Repository:chart-management-api、Module:chart-management-api/chart/core"
        },
        "nodeType": {
          "type": "string",
          "enum": ["Product", "Capability", "Component", "Interface", "Repository", "Module", "CodeEntity"]
        },
        "name": {"type": "string"},
        "validationState": {"$ref": "common.schema.json#/$defs/validationState"},
        "confidence": {"$ref": "common.schema.json#/$defs/confidence"},
        "evidence": {"type": "array", "items": {"type": "string"}, "description": "Evidence 記錄 id"},
        "governanceIssueRef": {"type": ["string", "null"]},
        "attrs": {"type": "object", "description": "nodeType 特有屬性（如 Repository 的 location／commit）"}
      }
    },
    "edge": {
      "type": "object",
      "required": ["id", "type", "from", "to", "evidence", "confidence", "validationState"],
      "properties": {
        "id": {"type": "string", "description": "穩定 id，建議 <type>|<from>|<to>"},
        "type": {
          "type": "string",
          "enum": ["REALIZES", "IMPLEMENTED_IN", "CONTAINS", "CALLS", "DEPENDS_ON", "IMPLEMENTS", "USES", "EXPOSES", "CONSUMES"]
        },
        "from": {"type": "string", "description": "from node id"},
        "to": {"type": "string", "description": "to node id"},
        "evidence": {
          "type": "array",
          "minItems": 1,
          "description": "無證據不產 edge；每筆為結構化證據（非 evidence id）",
          "items": {
            "type": "object",
            "required": ["evidenceType", "detail", "sourceRepo", "observedAt"],
            "properties": {
              "evidenceType": {
                "type": "string",
                "enum": ["api-usage", "openapi-client", "event-contract", "message-schema", "package-dependency", "helm-config-reference", "db-contract", "code-analysis", "human-input"]
              },
              "detail": {"type": "string", "description": "檔案路徑＋行號／套件版本／config 鍵值"},
              "sourceRepo": {"type": "string"},
              "commit": {"type": ["string", "null"]},
              "observedAt": {"type": "string", "format": "date-time"}
            }
          }
        },
        "confidence": {"$ref": "common.schema.json#/$defs/confidence"},
        "validationState": {"$ref": "common.schema.json#/$defs/validationState"},
        "governanceIssueRef": {"type": ["string", "null"]}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "pk/_schema/common.schema.json",
  "title": "PK Store Common Fields",
  "description": "所有 pk/ store 條目共用的 governance 欄位定義（供其他 schema $ref 引用）。對齊 docs/pk-conceptual-model.md 第 4 節與 docs/pk-storage-and-governance.md。",
  "$defs": {
    "validationState": {
      "type": "string",
      "enum": ["PROVISIONAL", "VALIDATED", "STALE", "CONFLICTING"],
      "description": "Observation／條目生命週期狀態（見 skills/pk-correlation-synthesis/SKILL.md）"
    },
    "confidence": {
      "type": "string",
      "enum": ["official-document", "meeting-consensus", "personal-share", "auto-observation"],
      "description": "可信度等級：官方文件 > 會議共識 > 個人分享；auto-observation＝中（自動觀察，待驗證）"
    },
    "sourceClass": {
      "type": "string",
      "enum": ["src-team-seed", "src-product-docs", "src-test-assets", "src-operations", "src-engineering", "src-code-delivery"],
      "description": "6 類 Knowledge Source（pk-conceptual-model.md 第 7 節）"
    },
    "pkClass": {
      "type": "string",
      "enum": ["pk-semantics", "pk-architecture", "pk-realization", "pk-governance"],
      "description": "四類 PK 主分類"
    },
    "governanceFields": {
      "type": "object",
      "required": ["id", "pkClass", "validationState", "confidence", "evidence", "governanceIssueRef"],
      "properties": {
        "id": {"type": "string", "minLength": 1, "description": "store 內唯一識別，建議格式 <類別前綴>:<path>，如 sem:spc/chart-management"},
        "pkClass": {"$ref": "#/$defs/pkClass"},
        "validationState": {"$ref": "#/$defs/validationState"},
        "confidence": {"$ref": "#/$defs/confidence"},
        "evidence": {
          "type": "array",
          "minItems": 1,
          "items": {"type": "string", "description": "pk/evidence/ 中 Evidence 記錄的 id"},
          "description": "證據參照列表；同一 fact 從多來源到達時全部列出，不重複建條目"
        },
        "governanceIssueRef": {
          "type": ["string", "null"],
          "description": "對應的 Multica ProductKB governance issue（id 或 URL）；雙向連結，issue 側以 store_ref 回指。尚無 issue 時為 null"
        },
        "sourceClass": {"$ref": "#/$defs/sourceClass"},
        "updatedAt": {"type": "string", "format": "date-time"},
        "supersedes": {"type": ["string", "null"], "description": "STALE 取代鏈：本條目取代的舊條目 id"},
        "supersededBy": {"type": ["string", "null"], "description": "STALE 取代鏈：取代本條目的新條目 id"}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "pk/_schema/realization-entry.schema.json",
  "title": "Product Realization Entry",
